package dev.amman.proficiency.skill;

import dev.amman.proficiency.perk.Expertise;
import dev.amman.proficiency.perk.ExpertiseNode;
import dev.amman.proficiency.perk.Synergies;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * The rules behind the Proficiency advancement tab (docs/ADVANCEMENTS.md). Every id here is an
 * advancement {@code proficiency:<id>} generated by {@code tools/gen_advancements.py}. The ones that
 * follow from saved state are worked out by {@link #earned}, so a veteran gets them on login and
 * after any change; the rest (a siege won, a proc landing, a Feast) are awarded where they happen.
 */
public final class Achievements {

    /** The levels that count, in every category. */
    public static final int[] LEVEL_TIERS = {10, 25, 50, 100};
    /** Biomes, dimensions and structures seen for "Well Travelled". */
    public static final int PLACES = 20;
    /** Total levels a death has to leave standing for "Only the Bars" (an average of 27 over 37 skills). */
    public static final int DEATH_LEVELS = 1000;
    public static final int STAGES = 6;
    public static final int SIEGE_LEVELS = 5;

    public static final String ROOT = "root";
    public static final String FIRST_STAR = "first_star";
    public static final String FIVE_STARS = "five_stars";
    public static final String JACK = "jack_of_all_trades";
    public static final String MASTER_OF_ALL = "master_of_all";
    public static final String FIRST_SYNERGY = "first_synergy";
    public static final String SIGNATURE_PROC = "first_signature_proc";
    public static final String FIRST_EXPERTISE = "first_expertise";
    public static final String EXPERTISE_FULL = "expertise_full";
    public static final String PLACES_ID = "hidden_places";
    public static final String FEAST = "hidden_feast";
    public static final String TALES = "hidden_tales";
    public static final String CHRONICLE = "hidden_chronicle";
    public static final String DEATH = "hidden_death";

    private Achievements() {
    }

    public static String level(SkillCategory category, int tier) {
        return "level_" + category.id() + "_" + tier;
    }

    public static String stage(int stage) {
        return "hearth_stage_" + stage;
    }

    public static String siege(int level) {
        return "siege_" + level;
    }

    /** Every id the mod can award, root first. */
    public static Set<String> all() {
        Set<String> ids = new LinkedHashSet<>();
        ids.add(ROOT);
        for (SkillCategory category : SkillCategory.values()) {
            for (int tier : LEVEL_TIERS) {
                ids.add(level(category, tier));
            }
        }
        ids.add(FIRST_STAR);
        ids.add(FIVE_STARS);
        ids.add(JACK);
        ids.add(MASTER_OF_ALL);
        ids.add(FIRST_SYNERGY);
        ids.add(SIGNATURE_PROC);
        ids.add(FIRST_EXPERTISE);
        ids.add(EXPERTISE_FULL);
        for (int i = 1; i <= STAGES; i++) {
            ids.add(stage(i));
        }
        for (int i = 1; i <= SIEGE_LEVELS; i++) {
            ids.add(siege(i));
        }
        ids.add(PLACES_ID);
        ids.add(FEAST);
        ids.add(TALES);
        ids.add(CHRONICLE);
        ids.add(DEATH);
        return ids;
    }

    /** What the saved state already earns. The root is always in it. */
    public static Set<String> earned(PlayerSkills skills) {
        Set<String> ids = new LinkedHashSet<>();
        ids.add(ROOT);
        int[] best = new int[SkillCategory.values().length];
        int lowest = Integer.MAX_VALUE;
        int topStars = 0;
        boolean anyStar = false;
        for (Skill skill : Skill.VALUES) {
            int level = skills.level(skill);
            SkillCategory category = skill.category();
            best[category.ordinal()] = Math.max(best[category.ordinal()], level);
            lowest = Math.min(lowest, level);
            int stars = skills.stars(skill);
            topStars = Math.max(topStars, stars);
            anyStar |= stars > 0;
        }
        for (SkillCategory category : SkillCategory.values()) {
            for (int tier : LEVEL_TIERS) {
                if (best[category.ordinal()] >= tier) {
                    ids.add(level(category, tier));
                }
            }
        }
        if (anyStar) {
            ids.add(FIRST_STAR);
        }
        if (topStars >= Mastery.MAX_STARS) {
            ids.add(FIVE_STARS);
        }
        if (lowest >= 10) {
            ids.add(JACK);
        }
        if (lowest >= SkillMath.MAX_LEVEL) {
            ids.add(MASTER_OF_ALL);
        }
        if (!Synergies.active(skills).isEmpty()) {
            ids.add(FIRST_SYNERGY);
        }
        if (skills.expertiseSpent() > 0) {
            ids.add(FIRST_EXPERTISE);
        }
        boolean full = true;
        for (ExpertiseNode node : Expertise.nodes()) {
            full &= skills.isExpertiseFull(node);
        }
        if (full) {
            ids.add(EXPERTISE_FULL);
        }
        if (skills.placesSeen() >= PLACES) {
            ids.add(PLACES_ID);
        }
        return ids;
    }

    /** "Only the Bars": a death that emptied real bars and still left a veteran's levels standing. */
    public static boolean onlyTheBars(int totalLevels, int barsLost) {
        return barsLost > 0 && totalLevels >= DEATH_LEVELS;
    }

    /** A siege horn level 1..SIEGE_LEVELS from the siege event, or 0 when the event did not say. */
    public static int siegeLevelOf(int eventLevel) {
        return Math.max(0, Math.min(SIEGE_LEVELS, eventLevel));
    }

    /** True for the milestone key a defended siege records ({@code <hearth key>|siege}). */
    public static boolean isSiegeMilestone(String key) {
        return key.endsWith("|siege");
    }

    /** The hearth stage a milestone key names ({@code <hearth key>|stage:N}), or 0. */
    public static int stageOfMilestone(String key) {
        int at = key.lastIndexOf("|stage:");
        if (at < 0) {
            return 0;
        }
        try {
            return Math.max(0, Math.min(STAGES, Integer.parseInt(key.substring(at + 7))));
        } catch (NumberFormatException e) {
            return 0;
        }
    }
}
